// puzzle.js: pure game logic (no DOM, no three.js).
// A level is a grid with one emitter on the edge, one receptor on the edge,
// rotatable mirrors, decoy mirrors and walls. Every level is generated by
// carving a real light route first, so each puzzle is always solvable.

export const T = { EMPTY: 0, MIRROR: 1, WALL: 2, SOURCE: 3, TARGET: 4 };

// 0 = east, 1 = north, 2 = west, 3 = south (y grows northward)
export const DIRS = [
  { x: 1, y: 0 },
  { x: 0, y: 1 },
  { x: -1, y: 0 },
  { x: 0, y: -1 },
];

// orient 0 = "/" mirror, orient 1 = "\" mirror
export function reflect(d, orient) {
  return orient === 0 ? d ^ 1 : 3 - d;
}

export const CAMPAIGN_LEVELS = 1000;
export const HARD_LEVELS = 6;

// Campaign difficulty, idx = 0..999. Every level adds at least one new challenge:
// decoy mirrors grow by one per level until they cap, then longer routes,
// bigger boards, more walls and more locked mirrors keep the climb going.
function campaignConfig(idx) {
  // Route length (= par) climbs one step at a time, from 3 to 17 mirrors.
  const turns = 3 + Math.floor(idx * 0.015);
  return {
    mode: 'campaign',
    n: Math.min(9, 5 + Math.floor(idx / 200)),
    minTurns: turns,
    maxTurns: turns,
    decoys: Math.min(80, 2 + idx),
    lockedChance: Math.min(0.5, idx / 2000),
    walls: Math.min(30, Math.floor(idx / 40)),
    timeLimit: 0,
    moveSlack: Infinity,
  };
}

export function levelConfig(mode, idx) {
  if (mode !== 'hard') return campaignConfig(idx);
  if (mode === 'hard') {
    return {
      mode,
      n: [7, 7, 8, 8, 9, 9][idx] ?? 9,
      minTurns: 6 + Math.floor(idx / 2),
      maxTurns: 11,
      decoys: 12 + idx * 2,
      lockedChance: 0.4,
      walls: 6 + idx,
      timeLimit: 150 - idx * 5,
      moveSlack: 1,
    };
  }
  return {
    mode: 'campaign',
    n: Math.min(7, 5 + Math.floor(idx / 3)),
    minTurns: 2 + Math.floor(idx / 2),
    maxTurns: 4 + Math.floor(idx / 2),
    decoys: Math.floor(idx * 1.2),
    lockedChance: idx > 6 ? 0.25 : 0,
    walls: Math.floor(idx / 2),
    timeLimit: 0,
    moveSlack: Infinity,
  };
}

const key = (x, y) => y * 64 + x;
const inBounds = (n, x, y) => x >= 0 && y >= 0 && x < n && y < n;
const onEdge = (n, x, y) => x === 0 || y === 0 || x === n - 1 || y === n - 1;

function emptyGrid(n) {
  const cells = [];
  for (let y = 0; y < n; y++) {
    const row = [];
    for (let x = 0; x < n; x++) {
      row.push({ x, y, type: T.EMPTY, orient: 0, dir: 0, locked: false, onPath: false, solution: 0, decoy: false, view: null });
    }
    cells.push(row);
  }
  return cells;
}

function pickSource(n) {
  const side = Math.floor(Math.random() * 4);
  const r = 1 + Math.floor(Math.random() * (n - 2));
  switch (side) {
    case 0: return { x: 0, y: r, dir: 0 };
    case 1: return { x: n - 1, y: r, dir: 2 };
    case 2: return { x: r, y: 0, dir: 1 };
    default: return { x: r, y: n - 1, dir: 3 };
  }
}

// Depth-first search with backtracking from the emitter. Finds a light route that ends
// on an edge cell (the receptor) after between minTurns and maxTurns mirror turns.
// Returns null if no route is found within the search budget (caller retries).
function carvePath(cells, n, minTurns, maxTurns) {
  const src = pickSource(n);
  const used = new Set([key(src.x, src.y)]);
  const chain = [];
  let budget = 20000;
  let end = null;

  function search(x, y, d, turns) {
    if (--budget < 0) return false;
    const nx = x + DIRS[d].x, ny = y + DIRS[d].y;
    if (!inBounds(n, nx, ny)) return false;
    if (onEdge(n, nx, ny)) {
      if (turns >= minTurns) { end = { x: nx, y: ny }; return true; }
      return false;
    }
    if (used.has(key(nx, ny))) return false;
    // 0 = straight through, 1 = mirror turning left, 2 = mirror turning right
    for (const o of shuffle([0, 1, 2])) {
      const nd = o === 0 ? d : o === 1 ? (d + 1) % 4 : (d + 3) % 4;
      const t2 = turns + (o ? 1 : 0);
      if (t2 > maxTurns) continue;
      used.add(key(nx, ny));
      chain.push({ x: nx, y: ny, turned: o > 0, nd, from: d });
      if (search(nx, ny, nd, t2)) return true;
      chain.pop();
      used.delete(key(nx, ny));
    }
    return false;
  }

  if (!search(src.x, src.y, src.dir, 0)) return null;

  const srcCell = cells[src.y][src.x];
  srcCell.type = T.SOURCE;
  srcCell.dir = src.dir;
  srcCell.onPath = true;
  const mirrors = [];
  for (const s of chain) {
    const cell = cells[s.y][s.x];
    cell.onPath = true;
    if (s.turned) {
      cell.type = T.MIRROR;
      cell.orient = (s.from ^ 1) === s.nd ? 0 : 1; // the mirror that turns "from" into "nd"
      mirrors.push(cell);
    }
  }
  const t = cells[end.y][end.x];
  t.type = T.TARGET;
  t.onPath = true;
  return { source: src, target: end, mirrors };
}

function shuffle(arr) {
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
}

// Follows the beam from the emitter. Returns the cell centres it passes through.
export function traceBeam(cells, n, src) {
  let x = src.x, y = src.y;
  let d = cells[src.y][src.x].dir;
  const points = [{ x, y }];
  const seen = new Set();
  let exit = 'loop';
  let reached = false;

  for (let i = 0; i < n * n * 4; i++) {
    const nx = x + DIRS[d].x, ny = y + DIRS[d].y;
    if (!inBounds(n, nx, ny)) { exit = 'edge'; break; }
    const c = cells[ny][nx];
    points.push({ x: nx, y: ny });
    if (c.type === T.TARGET) { reached = true; exit = 'target'; break; }
    if (c.type === T.WALL || c.type === T.SOURCE) { exit = 'wall'; break; }
    if (c.type === T.MIRROR) d = reflect(d, c.orient);
    x = nx; y = ny;
    const state = key(x, y) * 4 + d;
    if (seen.has(state)) { exit = 'loop'; break; }
    seen.add(state);
  }
  return { reached, points, exit, endDir: d };
}

// Generates a solvable level. `optimal` = fewest mirror turns needed from the scrambled start.
export function generateLevel(cfg) {
  // If a very long route cannot be carved, relax the turn count and try again.
  for (let minTurns = cfg.minTurns; minTurns >= 2; minTurns--) {
    const level = tryGenerate({ ...cfg, minTurns: Math.min(minTurns, cfg.minTurns) }, 40000);
    if (level) return level;
  }
  throw new Error('Level generation failed');
}

function tryGenerate(cfg, attempts) {
  const { n } = cfg;
  for (let attempt = 0; attempt < attempts; attempt++) {
    const cells = emptyGrid(n);
    const carved = carvePath(cells, n, cfg.minTurns, cfg.maxTurns);
    if (!carved) continue;
    const { source, target, mirrors } = carved;

    // Scramble the route's mirrors and remember the correct settings.
    // Every route mirror starts turned the wrong way, so par equals the route length.
    for (const m of mirrors) {
      m.solution = m.orient;
      m.orient = m.solution ^ 1;
    }
    let optimal = mirrors.filter((m) => m.orient !== m.solution).length;
    if (optimal === 0) {
      mirrors[0].orient ^= 1;
      optimal = 1;
    }
    // Decoys and walls only go on cells the route never touches.
    const free = [];
    for (let y = 1; y < n - 1; y++) {
      for (let x = 1; x < n - 1; x++) {
        if (!cells[y][x].onPath) free.push(cells[y][x]);
      }
    }
    shuffle(free);
    let i = 0;
    for (let k = 0; k < cfg.decoys && i < free.length; k++, i++) {
      const c = free[i];
      c.type = T.MIRROR;
      c.orient = Math.random() < 0.5 ? 0 : 1;
      c.locked = Math.random() < (cfg.lockedChance || 0);
      c.decoy = true;
    }
    for (let k = 0; k < cfg.walls && i < free.length; k++, i++) {
      free[i].type = T.WALL;
    }

    // Decoys can deflect a scrambled beam into a win by chance; reject those boards.
    if (traceBeam(cells, n, source).reached) continue;

    return { n, cells, source, target, optimal, cfg };
  }
  return null;
}
